schema:
CREATE TABLE competitor_event (
  competitor_id,
  event_id,
  medal_id
);

CREATE TABLE event (
  event_name,
  id,
  sport_id
);

CREATE TABLE games (
  games_name,
  games_year,
  id,
  season
);

CREATE TABLE games_competitor (
  age,
  games_id,
  id,
  person_id
);

CREATE TABLE noc_region (
  id,
  noc,
  region_name
);
